#include <chrono>
#include <iomanip>
#include <iostream>
#include <string_view>
#include <flat_map>

using namespace std::chrono;

int main() {
    const std::flat_multimap<year_month_day, int> messages{{February / 17 / 2023, 10},
        {February / 17 / 2023, 20}, {February / 16 / 2022, 30},
        {October / 22 / 2022, 40}, {June / 14 / 2022, 50}, {November / 23 / 2021, 60},
        {December / 10 / 2022, 55}, {December / 12 / 2021, 45}, {April / 1 / 2020, 42},
        {April / 1 / 2020, 24}};

    std::cout << "Messages received (date order is reversed):\n";
    for (auto it = messages.crbegin(); it != messages.crend(); ++it)
        std::cout << it->first << " : " << it->second << '\n';
}
